import { ElevenLabsClient } from "../../../src/Client";
import { mockServerPool } from "../../mock-server/MockServerPool";

describe("AccentsClient", () => {
    test("get", async () => {
        const server = mockServerPool.createServer();
        const client = new ElevenLabsClient({ maxRetries: 0, apiKey: "test", environment: server.baseUrl });

        const rawResponseBody = {
            accents: [{ accent: "american", language: "en", code: "en-american", name: "American" }],
        };

        server.mockEndpoint().get("/v1/voices/accents").respondWith().statusCode(200).jsonBody(rawResponseBody).build();

        const response = await client.voices.accents.get({
            language: "language",
            modelId: "model_id",
        });
        expect(response).toEqual({
            accents: [
                {
                    accent: "american",
                    language: "en",
                    code: "en-american",
                    name: "American",
                },
            ],
        });
    });
});
